(()=>{
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],toast=message=>{const el=$('#lightToast');el.textContent=message;el.classList.add('show');clearTimeout(window.lightToastTimer);window.lightToastTimer=setTimeout(()=>el.classList.remove('show'),2300)};
 const records=[{day:18,reference:'7080C002',production:'202602',line:'C3',tools:{CM:['ST100','12','B1 · B3','NNPB','16 peças'],MF:['5447','08','B3','NNPB','16 peças'],BQ:['T173','04','B3','—','144 peças']}},{day:18,reference:'5774T173',production:'202603',line:'B1',tools:{CM:['ST100','12','B1 · B3','NNPB','16 peças'],MF:['5447','08','B3','NNPB','16 peças'],BQ:['T173','04','B3','—','144 peças']}},{day:21,reference:'5810T188',production:'202602',line:'B2',tools:{CM:['ST100','12','B1 · B3','NNPB','16 peças'],MF:['5447','08','B3','NNPB','16 peças'],BQ:['T173','04','B3','—','144 peças']}}];
 let day=18,selected=null;const sheet=$('#lightSheet');
 function renderDays(){const root=$('#lightDays');root.replaceChildren();for(let i=0;i<5;i++)root.append(document.createElement('span'));for(let d=1;d<=31;d++){const button=document.createElement('button');button.type='button';button.textContent=d;button.className=(d===day?'selected ':'')+(records.some(r=>r.day===d)?'has':'');button.onclick=()=>{day=d;selected=null;renderDays();renderList()};root.append(button)}}
 function renderList(){const root=$('#lightProductionList');root.replaceChildren();const q=$('#lightSearch').value.trim().toLowerCase(),matches=records.filter(r=>r.day===day&&`${r.reference} ${r.production} ${r.line}`.toLowerCase().includes(q));$('#lightDayTitle').textContent=`Produções de ${day} de agosto`;$('#lightNoResults').hidden=matches.length>0;for(const record of matches){const button=document.createElement('button');button.type='button';button.className='beta-light-production'+(selected===record?' selected':'');button.innerHTML=`<strong>${record.reference}</strong><span>${record.production} · ${record.line}</span>`;button.onclick=()=>{selected=record;renderList()};button.ondblclick=()=>open(record);root.append(button)}}
 function showTools(record){const root=$('#lightTools');root.replaceChildren();for(const type of ['CM','MF','BQ']){const facts=record?.tools?.[type]||['','','','',''];const card=document.createElement('section');card.className='beta-light-tool';card.dataset.type=type;const title=document.createElement('h3');title.textContent=type;const input=document.createElement('input');input.type='search';input.setAttribute('aria-label',`Pesquisar ${type}`);input.placeholder=`Pesquisar ${type} por referência`;input.value=facts[0];const result=document.createElement('div');result.className='beta-light-tool-result';const select=document.createElement('button');select.type='button';select.textContent=`${type} ${facts[0]} · lote ${facts[1]}`;const info=document.createElement('small');info.textContent=[facts[2],facts[3],facts[4]].filter(x=>x&&x!=='—').join(' · ');result.append(select,info);result.hidden=!facts[0];const missing=document.createElement('a');missing.className='dmo-button ghost';missing.textContent=`Criar ${type}`;missing.hidden=true;missing.href='tool-create.html';input.oninput=()=>{const found=!!facts[0]&&facts[0].toLowerCase().includes(input.value.trim().toLowerCase());result.hidden=!found;missing.hidden=!input.value.trim()||found;missing.href=`tool-create.html?from=jobon&type=${type}&reference=${encodeURIComponent(input.value.trim())}`};select.onclick=()=>{input.value=facts[0];toast(`${type} selecionado`)};missing.onclick=()=>sessionStorage.setItem('lightJobDraft',JSON.stringify({reference:$('#lightReference').value,production:$('#lightProduction').value,line:$('#lightMachine').value,start:$('#lightStart').value,end:$('#lightEnd').value}));card.append(title,input,result,missing);root.append(card)}}
 function open(record){selected=record||null;sheet.hidden=false;$('#lightReference').value=record?.reference||'';$('#lightProduction').value=record?.production||'';$('#lightMachine').value=record?.line||$('.beta-light-lines .active')?.dataset.line||'B1';$('#lightStart').value='';$('#lightEnd').value='';showTools(record);sheet.scrollIntoView({behavior:'smooth',block:'start'})}
 $$('.beta-light-tabs [data-light-view]').forEach(button=>button.onclick=()=>{$$('.beta-light-tabs button').forEach(x=>x.classList.toggle('active',x===button));$$('[data-light-panel]').forEach(x=>x.classList.toggle('active',x.dataset.lightPanel===button.dataset.lightView))});
 $$('#lightLines button').forEach(button=>{button.onclick=()=>{$$('#lightLines button').forEach(x=>x.classList.toggle('active',x===button));const match=records.find(r=>r.line===button.dataset.line);if(match){day=match.day;selected=match;renderDays();renderList()}else{selected=null;renderList()}};button.ondblclick=()=>{const match=records.find(r=>r.line===button.dataset.line);if(match)open(match)}});
 $('#lightSearch').oninput=renderList;$('#lightNew').onclick=()=>open(null);$('#lightClose').onclick=()=>sheet.hidden=true;$('#lightDuplicate').onclick=()=>{const previous=records.find(r=>r.reference===$('#lightReference').value&&r!==selected);if(!previous){toast('Sem produção anterior desta referência');return}const production=$('#lightProduction').value;open(previous);$('#lightProduction').value=production;toast('Dados da produção anterior copiados; confirme antes de guardar')};$('#lightForm').onsubmit=e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;toast('Rascunho do Job On preparado nesta demonstração')};
 const draft=sessionStorage.getItem('lightJobDraft');if(new URLSearchParams(location.search).has('toolCreated')&&draft){try{const data=JSON.parse(draft);open(null);$('#lightReference').value=data.reference;$('#lightProduction').value=data.production;$('#lightMachine').value=data.line;$('#lightStart').value=data.start;$('#lightEnd').value=data.end}catch(e){}sessionStorage.removeItem('lightJobDraft')}
 const requested=new URLSearchParams(location.search).get('view');if(requested==='history')$('.beta-light-tabs [data-light-view="history"]').click();if(requested==='sheet')open(records[0]);renderDays();renderList();
})();
